#!/usr/bin/env python3
"""Russia flagship data 5: RU-32 to RU-38 (HELD for a lawyer's check). Own wording; no brand, institution or person names; no course fees."""

C32 = dict(
 id='RU-32', title='Personal Assistants for the Elderly',
 summary='Learn to plan and deliver safe, respectful non-medical support for older adults at home: daily routines, mobility, meals, reminders, errands, communication and knowing when to call for help.',
 level='L4 Practitioner',
 outcomes=[('Understand', 'Explain the limits between personal assistance, nursing and medical care, and why each limit exists.'),
  ('Apply', 'Carry out a safe transfer, a meal and hydration routine and a home safety check using a written checklist.'),
  ('Analyse', 'Assess one older person\'s needs, risks and preferences and rank them by urgency.'),
  ('Evaluate', 'Judge an incident and decide whether to act, record, escalate or call emergency services.'),
  ('Create', 'Design a four-week support plan with visit times, tasks, records and a review date.')],
 task='Produce a four-week support plan and a first-visit assessment for one older person (a role-play client or a consenting volunteer), with a home safety check, a daily routine, a record sheet and an escalation sheet.',
 condition='Open-book; 6 hours over one week; templates, a pen, a tape measure and a calculator; a role-play client or a written case; no medical advice given.',
 standard='All 5 documents complete; at least 8 of 10 risks found in the case home; every task inside the non-medical boundary; escalation contacts named; pass mark 80 percent on the rubric.',
 who='People who want to work as a personal assistant, companion or home helper for older adults, and family members who care for a relative.',
 req='Adult learner; patience and respect for privacy; basic reading and arithmetic. A clean record check and a health check may be required by employers or by the competent authority.',
 safety='This course is not nursing or medical training. A personal assistant does not diagnose, change treatment, give injections or decide doses. Social-care services may need registration, a contract and checks under the relevant federal and regional rules; check with the competent Russian authority and a local adviser before offering paid care. Always call emergency services for chest pain, stroke signs, serious falls, choking or unresponsiveness.',
 evidence='Evidence: assessment form, home safety checklist, four-week plan, visit record sheet, escalation sheet and a short reflection on one boundary decision.',
 modules=[
 ('Role, boundaries and dignity', 'Understand', 4,
  'A personal assistant supports daily living. Clear limits protect the older person and the assistant, and respect keeps the person in charge of their own life.',
  ['Separate three roles: personal assistance (company, meals, errands, reminders), nursing care (wound care, injections) and medical care (diagnosis, treatment). Only the first is yours.',
   'Ask for consent before every task, even a small one: "May I help you with your coat?" Consent can be withdrawn at any time.',
   'Keep personal information private. Share it only with the client, named family and the supervisor, and only what is needed.',
   'Write a one-page job description with tasks you will do, tasks you will not do and who you call for the rest.'],
  'A client asks you to adjust her blood pressure tablet because she feels dizzy. Correct response: do not change anything, sit her down, check she is safe, call her doctor or the family contact, and record the time and what she said. A 20-minute call beats a wrong dose.',
  'Sort 12 tasks (for example "cut toenails of a diabetic client", "fetch bread", "give an injection") into do, do with training, and never do. Explain two choices aloud.',
  'At least 11 of 12 tasks sorted correctly; each "never do" has a named person to call.'),
 ('Needs and risk assessment', 'Analyse', 5,
  'Good support starts by listening and observing. An assessment records what the person can do, wants to do and finds hard.',
  ['Use a simple domains list: mobility, eating and drinking, washing and dressing, memory, mood and company, home, money and errands.',
   'Observe and ask, never assume. Record "walks 10 m with a stick, rests twice" rather than "weak".',
   'Rate each risk as likelihood (1 to 3) times effect (1 to 3). A score of 6 or more needs action in the first week.',
   'Record what matters to the person: favourite meal, daily rhythm, hobbies, who they want to see.'],
  'Case: Mr A, 82, lives on the 4th floor without a lift. Falls risk likelihood 3, effect 3 = 9 (action now). Missed meals likelihood 2, effect 2 = 4 (monitor). Loneliness 3 x 2 = 6 (action in week one: two social visits per week).',
  'Complete the assessment form for a written case or a role-play client. Score at least 8 risks and rank them.',
  'All seven domains covered; scores calculated correctly; top three risks have a named action and a date.'),
 ('Safe movement and the home', 'Apply', 5,
  'Falls are among the most serious everyday risks for older people. Most can be reduced with simple changes and safe technique.',
  ['Check the home room by room: loose rugs, cables, poor light, wet floors, missing handrails, unreachable shelves, steep thresholds.',
   'Never pull a person by the arm. Ask them to move forward on the seat, feet flat, lean forward, and stand on a count of three while you guard.',
   'Keep a clear route of at least 90 cm to the toilet and fit a night light. Place often-used items between knee and shoulder height.',
   'After a fall, do not lift at once. Check for pain, head injury or confusion, keep the person warm, and call for help if in doubt.'],
  'Hallway of 80 cm with a rug and a 60 W bulb. Actions: remove the rug (0 RUB), clear shelf items to give 90 cm, fit a 9 W LED lamp bright enough to read by (about 250 RUB), tape cables. Risk score falls from 9 to 3.',
  'Run a 20-item home safety checklist in a room of your own home. List 6 changes, their cost in RUB and their order.',
  'At least 15 of 20 items checked; six changes ranked by risk; one safe stand-up demonstrated.'),
 ('Food, drink and reminders', 'Apply', 5,
  'Older people can lose appetite and thirst. Regular meals, drinks and agreed reminders keep strength up, and the assistant stays inside the medication boundary.',
  ['Offer a drink with every visit and every meal. A common general target is about 1.5 litres of fluid a day unless a doctor has set a limit; ask the family for the limit.',
   'Plan three meals and two snacks a day, soft or small portions if chewing is hard, and check food dates and storage (fridge at 0 to 5 degrees Celsius).',
   'Reminders: you may remind a person to take tablets from a pre-filled organiser set up by the person, family or pharmacist. You do not choose, split or change doses.',
   'Record what was eaten and drunk in simple units (cups, portions) and report a big change within the day.'],
  'Target 1,500 ml a day. A cup is 200 ml: 7 cups reach 1,400 ml; add a 200 ml soup to pass 1,500 ml. A weekly shop for one person planned at 2,400 RUB = about 343 RUB per day.',
  'Write a 3-day menu with drinks for a client who has poor teeth and a low appetite, plus the shopping list and cost.',
  'Fluid plan reaches the target; menu fits the stated difficulty; reminder rules written with the boundary.'),
 ('Communication, memory and mood', 'Apply', 4,
  'How you speak decides whether help is accepted. Calm, clear and unhurried communication reduces fear and conflict.',
  ['Face the person, speak slowly, use short sentences and one idea at a time. Check hearing aids and glasses are in use.',
   'With memory problems, do not argue about facts. Acknowledge the feeling, redirect gently and keep routines the same.',
   'Watch for low mood: poor sleep, loss of interest, not eating, talk of being a burden. Report to family or doctor; any talk of self-harm needs urgent help the same day.',
   'Offer choices of two ("tea or compote?") rather than open questions.'],
  'Client repeats the same question 6 times in an hour. Poor response: "I already told you." Better: answer calmly each time, write the answer on a card by the chair, then start a favourite activity for 15 minutes.',
  'Role-play three scenes (refusal of a bath, repeated question, sadness) for 5 minutes each with a peer who scores you.',
  'Peer score of 4 out of 5 or better on calm tone, choice offered and no argument.'),
 ('Errands, money and paperwork', 'Apply', 4,
  'Handling someone else\'s money or papers is a trust task. Clear rules and receipts protect everyone.',
  ['Use a written authority for errands, an agreed spending limit and a receipt for every purchase. Keep your money and theirs apart.',
   'Never accept gifts of value, loans, a will role or access to bank cards and PIN numbers. Tell the family if offered.',
   'Warn against telephone and doorstep scams. A caller who needs money or codes quickly is a red flag; hang up and ring the family.',
   'Help with forms by reading and explaining, not by deciding. Keep copies in a labelled folder.'],
  'Float of 3,000 RUB given on Monday. Receipts: bread 120, milk 95, pharmacy item 640, vegetables 410 = 1,265 RUB. Change returned 1,735 RUB. Sheet signed by both.',
  'Fill in a spending ledger for a week of 8 purchases, with receipts and change, and write a three-line scam script.',
  'Ledger balances to the ruble; no cash mixing; scam script names the person to call.'),
 ('Emergencies, safeguarding and escalation', 'Evaluate', 5,
  'You will meet worrying signs. Knowing what to do in the first minutes, and whom to tell, is the most important skill in the job.',
  ['Call emergency services at once for stroke signs (face drooping, arm weakness, speech trouble), chest pain, breathlessness, choking, unresponsiveness or a serious fall.',
   'Learn the signs of neglect or abuse: unexplained bruises, fear of a person, missing money, no food. Report to your supervisor and the competent authority; do not confront.',
   'Keep an emergency sheet by the phone: address with entrance and floor, diagnoses, allergies, medicines list, doctor and family numbers.',
   'Record facts, times and words used, not opinions. Sign and date every record.'],
  'You find a client on the floor at 10:05, awake but unable to stand. Timeline: 10:05 safe check and call; 10:07 emergency call, address given with entrance code; 10:09 keep warm; 10:25 crew arrives; 10:40 family informed; 11:00 record written.',
  'Judge five short incident cards: choose call-now, same-day report or next-visit note, and justify each in one line.',
  'At least 4 of 5 judged correctly; every call-now case names what you say on the phone.'),
 ('Design a support plan', 'Create', 4,
  'A plan joins everything: needs, visits, tasks, records and review. It should be clear enough for a stand-in to follow.',
  ['Set visit times to match the person\'s day, not yours. Add a task list for each visit with time estimates.',
   'Cost the plan honestly: hours, travel time and expenses. Show the person and family the cost before starting.',
   'Include a review at week two and week four, and a list of changes that trigger an early review (a fall, a hospital stay, a new medicine).',
   'Add a handover page so another assistant could cover a visit.'],
  'Plan: 3 visits a week x 2 hours = 6 hours; at a posted rate of 450 RUB per hour = 2,700 RUB per week, 10,800 RUB for 4 weeks, plus about 300 RUB per week travel = 12,000 RUB. Review dates on day 14 and day 28.',
  'Build the four-week plan, the cost sheet, the record sheet and the handover page for your case.',
  'All tasks within boundary; cost adds up; two review dates and three early-review triggers present.')],
 quiz=[('Name the three roles that must stay separate.', 'Personal assistance, nursing care and medical care. A personal assistant does only the first.'),
  ('A client wants you to double a tablet dose. What do you do?', 'Do not change it. Make her safe, contact her doctor or family, and record the request and time.'),
  ('How do you stand a person up safely?', 'Feet flat, move forward on the seat, lean forward, stand on a count of three, guard without pulling the arm.'),
  ('What is a general daily fluid target and its caveat?', 'About 1.5 litres a day unless a doctor has set a limit.'),
  ('Score a risk with likelihood 3 and effect 2. What action level?', '3 x 2 = 6. This needs action in the first week.'),
  ('What do you do when a client repeats the same question many times?', 'Answer calmly, write it on a card, redirect to an activity, and do not argue.'),
  ('List two scam warning signs.', 'Pressure to act quickly, requests for money, codes or card details by phone or at the door.'),
  ('When must you call emergency services at once?', 'Stroke signs, chest pain, breathlessness, choking, unresponsiveness or a serious fall.'),
  ('What belongs on an emergency sheet?', 'Address with entrance and floor, diagnoses, allergies, medicines, doctor and family numbers.'),
  ('Why do you cost the plan before starting?', 'So the person and family agree to the hours, price and expenses, which avoids disputes.')],
 rubric=[('Boundaries and consent', 'Tasks cross into nursing or medicine.', 'All tasks inside the non-medical boundary with consent noted.', 'Also explains why each limit exists and who covers the gap.'),
  ('Assessment quality', 'Few domains; vague notes.', 'All domains; risks scored and ranked.', 'Adds the person\'s own goals and a clear priority logic.'),
  ('Safety and technique', 'Misses obvious hazards.', 'Finds most hazards; safe stand-up shown.', 'Ranks fixes by risk and cost with a time order.'),
  ('Records and money', 'Missing or unsigned records; ledger does not balance.', 'Records dated and signed; ledger balances.', 'Handover page lets a stand-in work alone.'),
  ('Escalation judgement', 'Delays or over-reacts.', 'Chooses the right level for 4 of 5 cases.', 'Gives exact words for the call and a family update.')],
 ladder=['L1 Basic: recognise the difference between helping, nursing and medical care (note: awareness only).',
  'L2 Awareness: describe common age-related needs and the signs that need urgent help.',
  'L3 Foundation: assist with simple tasks such as meals, shopping and company under supervision.',
  'L4 Practitioner: assess one person, run a home safety check and deliver a four-week plan on your own.',
  'L5 Specialist: adapt support for memory loss, reduced mobility or post-hospital recovery with a care team.',
  'L6 Advanced: supervise assistants, audit records and design a small service with training and quality checks.',
  'L7 Super expert: lead service standards and advise on policy and safeguarding systems (note: always within the law and regulator rules).'],
 jobs=[('Personal assistant to an older person', 'Provides non-medical daily support in the client\'s home.'),
  ('Companion carer', 'Offers company, outings and routine support.'),
  ('Care coordinator assistant', 'Schedules visits, keeps records and liaises with families.'),
  ('Home safety adviser (older adults)', 'Checks homes and suggests low-cost safety changes.'),
  ('Day-centre support worker', 'Helps run activities and meals for older people.')],
 next='Related generic courses: Home Care Assistance, Childcare and Family Support, Health and Safety Basics.')

C33 = dict(
 id='RU-33', title='Salvaging',
 summary='Learn to recover, grade, clean, test, price and resell used goods and materials safely and lawfully, and to keep the records that show where every item came from and where it went.',
 level='L4 Practitioner',
 outcomes=[('Understand', 'Explain the salvage chain from sourcing to resale and the legal and safety limits on each step.'),
  ('Apply', 'Grade a mixed lot by condition and material using a written grading key and weigh it with a calibrated scale.'),
  ('Analyse', 'Calculate landed cost, recovery rate and margin per kilogram or per item for a lot.'),
  ('Evaluate', 'Judge whether a lot is worth taking, needs a licensed handler, or must be refused.'),
  ('Create', 'Design a small salvage workflow with intake, sorting, storage, sales and a record book.')],
 task='Take one mixed lot (real or written case of 200 kg to 500 kg), grade it, cost it, plan its disposal and resale routes, and complete the intake and sales records.',
 condition='Open-book; 5 hours; gloves, scale, notebook, calculator and a grading key; hazardous items are identified on paper only, never handled.',
 standard='Lot graded into at least 5 classes; weights sum to the intake weight within 2 percent; margin calculated to the ruble; every hazardous item routed to a licensed handler; pass mark 80 percent.',
 who='People who want to start or improve a small business recovering and reselling used goods, furniture, textiles, scrap metal, electronics parts or building materials.',
 req='Adult learner; ability to lift safely and use a calculator. A lawful place to store goods is needed.',
 safety='Salvage can involve waste law, scrap-metal and secondhand-trade rules, stolen-goods risk, asbestos, batteries, refrigerants, electrical hazards and sharp or heavy items. Handling, storing and transporting waste may need a licence or registration; trade in some metals and goods is restricted or recorded. Check with the competent Russian authority and a local adviser before you start. Never take goods without the owner\'s written permission, and never open or burn items of unknown content.',
 evidence='Evidence: sourcing agreement, intake record, grading sheet, hazard routing sheet, costing sheet, sales ledger and a workflow diagram.',
 modules=[
 ('The salvage chain and the law', 'Understand', 4,
  'Salvage turns discarded goods into value through a chain of lawful steps. Each step has a rule about ownership, waste status and records.',
  ['Map the chain: source, permission, collection, intake, sorting, cleaning or repair, storage, sale, remainder to disposal.',
   'Ask who owns the goods and whether they are legally waste. Waste may need a licensed carrier and a transfer record under the relevant federal rules.',
   'Never accept goods you suspect are stolen. Ask for a written release, keep copies of identity and note the date and vehicle.',
   'Keep a record book: date, source, description, weight, price paid or free, and where each item went.'],
  'A shop gives 300 kg of used shelving, steel and wood. You note: 180 kg steel, 90 kg wood, 30 kg plastic. Total 300 kg matches the weighbridge slip. The release letter names the shop and the date.',
  'Draw the salvage chain for one product and mark the three points where a licence, permit or record may be needed.',
  'Chain shows all nine steps; three legal control points named; sample record line complete.'),
 ('Sourcing and permission', 'Apply', 4,
  'Good sources are steady, clean and legal. A written agreement saves arguments later.',
  ['Source types: shops closing, offices refitting, households clearing, building sites, repair shops, event organisers.',
   'Agree in writing: what you take, when, who loads, who pays for transport, and what happens to leftovers.',
   'Visit before accepting. Take photographs and estimate volume in cubic metres and weight in kilograms.',
   'Say no to unsafe lots: unknown liquids, medical waste, broken glass heaps, wet insulation, items with damaged asbestos-like boards.'],
  'An office clears 40 chairs and 12 desks. Estimated 40 x 6 kg + 12 x 25 kg = 540 kg and about 9 cubic metres. A 3-tonne van with 12 cubic metres needs one trip.',
  'Write a one-page sourcing agreement and a site-visit checklist, and estimate weight and volume for a case.',
  'Agreement covers 5 items; estimate within 15 percent of the key.'),
 ('Safe handling and hazards', 'Evaluate', 5,
  'Most salvage injuries and legal problems come from hazards that were not noticed in time.',
  ['Wear gloves, safety shoes and eye protection. Lift with a straight back; share loads above 20 kg.',
   'Spot the hazards: batteries and capacitors, refrigerant circuits, mercury lamps, sealed cans, broken glass, mould, old paint, board or roofing that may contain asbestos.',
   'Do not cut, drill or burn suspect material. Stop, isolate, photograph and call a licensed handler.',
   'Keep a hazard routing sheet: item, hazard, action, who takes it, date.'],
  'Lot of 20 old fridges. Each has a refrigerant circuit and compressor oil. They cannot be cut. Action: keep upright, intact, send 20 units to a licensed recycler. Resale of working units after test: 4 of 20.',
  'Classify 15 items on a picture sheet as take, take with limits, or refuse. Explain 5 choices.',
  'At least 14 of 15 correct; every refusal names the safer route.'),
 ('Grading and sorting', 'Apply', 4,
  'A clear grading key makes value visible. Sort by material, condition and test result.',
  ['Use grades A (resell as is), B (clean or repair), C (parts), D (material recycling), E (disposal).',
   'Weigh each class on a scale checked with a known 10 kg weight. Record to 0.1 kg.',
   'Keep similar items together and label bins. Mixed bins lose value because buyers want a clean grade.',
   'Check totals: class weights plus loss must equal intake weight within 2 percent.'],
  'Intake 400.0 kg. A 60.0, B 120.0, C 90.0, D 110.0, E 14.0 = 394.0 kg. Difference 6.0 kg = 1.5 percent, within the 2 percent limit.',
  'Grade a lot of 30 written items and balance the weights.',
  'Totals within 2 percent; each item has one grade and one reason.'),
 ('Cleaning, testing and repair', 'Apply', 5,
  'Light work can raise value a lot, but only where it is safe and legal. Electrical items need testing, not guessing.',
  ['Set a limit on time per item. If repair time times your hourly value is more than the gain, move the item to parts.',
   'Clean safely with mild detergents. Never mix cleaners. Ventilate the space.',
   'Electrical goods: visual check of cable and plug, insulation test by a competent person, and mark tested items. Sell untested ones as parts only.',
   'Give honest descriptions: working, tested, parts only. False claims cause returns and disputes.'],
  'A chair costs 0 RUB. Repair needs a 40 RUB screw set and 20 minutes. Valued at 500 RUB per hour, labour is 167 RUB. Sale 900 RUB. Gain = 900 - 40 - 167 = 693 RUB.',
  'Calculate the repair-or-parts decision for 6 items using a table.',
  'Each decision shows time, material, labour value and gain; 5 of 6 correct.'),
 ('Pricing, channels and sales', 'Analyse', 5,
  'Price from cost, condition and what buyers pay. Match each grade to the right channel.',
  ['Channels: direct to customers, local shop or market stall, online listing, trade buyers by weight, and recyclers for material grades.',
   'Cost = purchase + transport + labour + storage + fees. Set a floor price at cost plus the margin you need.',
   'List accurately: photographs, size in centimetres, weight, defects, honest grade.',
   'Track sell-through: items sold divided by items listed, and days in stock.'],
  'Steel scrap grade D: 110 kg at 18 RUB per kg = 1,980 RUB. Transport 400 RUB, labour 2 hours at 300 RUB = 600 RUB. Net = 1,980 - 400 - 600 = 980 RUB.',
  'Price 10 items and choose a channel for each with a reason.',
  'Floor price shown for each item; channel fits grade; net margin calculated correctly.'),
 ('Records, storage and compliance', 'Evaluate', 4,
  'Records protect you in a dispute and prove goods were lawful. Storage rules protect people and goods.',
  ['Keep an intake record, a sales record and a waste transfer record with signatures and dates.',
   'Store dry, off the floor, with aisles at least 1 metre wide and a clear exit. Keep flammables away and have an extinguisher.',
   'Check tax and registration needs for sales and trade. Ask the competent authority and an adviser.',
   'Review monthly: stock age, space used, losses, incidents and complaints.'],
  'Monthly review: 2,000 kg in, 1,740 kg sold or recycled, 120 kg disposed, 140 kg still in stock; 2,000 = 1,740 + 120 + 140. Stock over 90 days: 35 kg, marked for price cut.',
  'Complete a mock month of records for 12 lines and find the 2 planted errors.',
  'Both errors found; stock reconciles; compliance checklist complete.'),
 ('Design a salvage workflow', 'Create', 4,
  'Bring all the steps into a small workflow another person could follow.',
  ['Draw the floor plan with zones: intake, hazards hold, sorting, repair, storage, dispatch.',
   'Write standard steps for intake, with a refuse list, weighing, labelling and photographing.',
   'Set weekly targets: kilograms in, kilograms sold, recovery rate (sold divided by in), and incidents (aim for zero).',
   'Set a review rule: stop a source if more than 20 percent of its weight is grade E.'],
  'Weekly target: 600 kg in, 480 kg sold = recovery rate 80 percent. Source X sent 200 kg of which 50 kg was grade E = 25 percent, above 20 percent, so review the source.',
  'Produce the floor plan, the intake procedure, the record sheet and the weekly target sheet.',
  'All four documents complete; recovery rate and source review rule worked correctly.')],
 quiz=[('Why check who owns goods before you take them?', 'To avoid handling stolen goods and to know whether the goods are legally waste.'),
  ('What must be done with refrigerators before recycling?', 'Keep them intact and send them to a licensed recycler; the refrigerant must not be released.'),
  ('How do you check a grading balance?', 'Class weights plus loss must equal intake within 2 percent.'),
  ('A repair gains 693 RUB; another costs 800 RUB in time for 600 RUB sale. Which do you do?', 'Do the first. The second loses money, so sell it for parts.'),
  ('Name three hazards you must not cut or burn.', 'Suspect asbestos board, sealed cans or pressurised items, batteries and fridge circuits.'),
  ('What is recovery rate?', 'Sold or recycled weight divided by weight in, as a percent.'),
  ('Why photograph at intake?', 'To prove condition and quantity, and to support the listing and any dispute.'),
  ('What is the minimum clear aisle width in storage in this course?', 'At least 1 metre.'),
  ('How do you price an item?', 'Add all costs, add the margin you need to set a floor, then compare with what buyers pay.'),
  ('When do you refuse a lot?', 'When it is unsafe, unlawful, of unknown origin or needs a licence you do not hold.')],
 rubric=[('Legal and ownership', 'Takes goods without a release.', 'Written release and records kept.', 'Also marks licence points and a plan to confirm them.'),
  ('Hazard judgement', 'Misses or handles hazards.', 'Routes all hazards correctly.', 'Gives a safer route and cost for each.'),
  ('Grading and weights', 'Totals do not balance.', 'Within 2 percent; one grade per item.', 'Within 1 percent with reasons recorded.'),
  ('Costing and margin', 'Costs left out.', 'All costs included; margin right.', 'Adds sensitivity for price falls of 10 percent.'),
  ('Workflow design', 'No clear steps.', 'Zones, steps and targets present.', 'Includes source review and improvement actions.')],
 ladder=['L1 Basic: name common reusable materials and say why safety and permission come first (awareness only).',
  'L2 Awareness: explain the salvage chain and the main hazards.',
  'L3 Foundation: sort and weigh a simple lot under supervision.',
  'L4 Practitioner: grade, cost, route and sell a mixed lot with full records.',
  'L5 Specialist: specialise in one stream such as metals, electronics parts or building materials with licensed partners.',
  'L6 Advanced: run a yard with several staff, audits and supplier contracts.',
  'L7 Super expert: design regional reuse networks and advise on policy (note: always inside waste rules and licences).'],
 jobs=[('Salvage yard assistant', 'Sorts, weighs and labels incoming goods.'),
  ('Reuse shop operator', 'Prices and sells repaired and tested goods.'),
  ('Collection coordinator', 'Plans pick-ups and agreements with sources.'),
  ('Materials sorter', 'Separates material streams for recyclers.'),
  ('Small salvage business owner', 'Runs intake, sales and records for a licensed operation.')],
 next='Related generic courses: Recycling and Waste Management, Furniture Repair and Upcycling, Small Business Records.')

C34 = dict(
 id='RU-34', title='Rentals Businesses (Vehicles, Tools, Machines)',
 summary='Learn how to plan and run a small rental business for vehicles, hand and power tools or light machines: fleet choice, pricing, contracts, inspections, maintenance, insurance and damage handling.',
 level='L4 Practitioner',
 outcomes=[('Understand', 'Explain how a rental business earns income and where it loses it: idle time, damage, late returns and downtime.'),
  ('Apply', 'Complete a check-out and check-in inspection with photographs and a signed condition report.'),
  ('Analyse', 'Calculate utilisation, cost per rental day and the break-even number of rental days per item.'),
  ('Evaluate', 'Judge a customer request for suitability, risk and required licence or training before agreeing.'),
  ('Create', 'Design a rental offer with a price list, deposit rule, contract terms and maintenance plan.')],
 task='Design a complete rental setup for a fleet of 5 to 10 items, with a price list, contract, inspection form, maintenance plan and monthly performance sheet.',
 condition='Open-book; 6 hours; templates, calculator and sample items on paper; no real customer data used.',
 standard='Price list covers cost plus margin; utilisation and break-even calculated without error; inspection form has at least 12 check points; contract names 8 required terms; pass mark 80 percent.',
 who='People who plan to rent vehicles, tools or machines in a small or home-based business, and staff of existing rental counters.',
 req='Adult learner; basic arithmetic. For vehicle rental, a lawful place to park and a business registration are needed.',
 safety='Vehicle and machine rental can be regulated: business registration, vehicle roadworthiness, insurance, driver licence category checks, safe use of lifting or cutting machines, and consumer rights all apply. Some machines need trained operators. Check with the competent Russian authority and a local adviser, and have a lawyer check the contract, before renting to anyone. Never rent out equipment you know to be unsafe.',
 evidence='Evidence: fleet and cost sheet, price list, contract with required terms, inspection form with sample entries, maintenance schedule and a monthly performance sheet.',
 modules=[
 ('How rental earns and loses money', 'Understand', 4,
  'A rental item is an asset that earns only when it is out. The business is about keeping items safe, available and well used.',
  ['Income per item = rental days x daily rate. Costs are fixed (purchase, insurance, storage, registration) and variable (cleaning, fuel, wear, repair).',
   'Utilisation = days rented divided by days available. Low utilisation means high cost per rental day.',
   'Typical losses: idle stock, late returns, damage without evidence, unpaid deposits, and downtime for repairs.',
   'Match fleet to demand: a small number of popular items beats a large number of rarely used ones.'],
  'A power drill costs 9,000 RUB, expected life 3 years of 365 days. Daily ownership cost is about 8.2 RUB (9,000 / 1,095). If it is rented 60 days a year at 300 RUB, income is 18,000 RUB a year, utilisation 16 percent.',
  'Choose five items and make a table of purchase cost, life, daily ownership cost and expected utilisation.',
  'Daily cost computed for all five; utilisation figures labelled as estimates.'),
 ('Fleet choice and cost per day', 'Analyse', 5,
  'Choose items your customers need and that you can maintain. Work out the true cost per rental day before pricing.',
  ['Survey local demand: ask 20 people which items they have hired or wished to hire, and for how long.',
   'Prefer common models with spare parts available and simple servicing.',
   'Cost per rental day = (yearly fixed + yearly variable cost) divided by days rented per year.',
   'Add 10 to 15 percent for unplanned repair.'],
  'Mini excavator: yearly fixed 120,000 RUB (depreciation, insurance, storage), variable 40,000 RUB, repair reserve 15 percent of 160,000 = 24,000 RUB. Total 184,000 RUB. At 80 rental days: 2,300 RUB per day cost.',
  'Calculate cost per rental day for three items at 3 utilisation levels and choose the best two.',
  'Calculations correct to the ruble; repair reserve included; choice explained.'),
 ('Pricing, deposits and add-ons', 'Apply', 4,
  'A price list should cover cost, give a fair margin and make the terms clear. Deposits protect against loss.',
  ['Price tiers: hourly, daily, weekend, weekly. Longer rentals have lower daily rates.',
   'Price = cost per rental day + margin, then check against what local customers accept.',
   'Deposit equals a part of replacement value or a fixed sum, returned after inspection. State when and how it is refunded.',
   'Add-ons: delivery, cleaning, fuel, insurance and accessories, each priced separately and shown at the start.'],
  'Excavator cost 2,300 RUB per day; margin 30 percent gives 2,990 RUB, rounded to 3,000 RUB per day. Week rate 5 days charged for 7: 15,000 RUB. Deposit 20,000 RUB.',
  'Build a tiered price list for two items with deposit and add-ons.',
  'Each tier covers cost; deposit and refund rule stated; no hidden fees.'),
 ('Contracts and customer checks', 'Evaluate', 5,
  'A good rental contract is plain, fair and complete. A good customer check prevents most problems.',
  ['Required terms: parties, item, serial number, period, price, deposit, condition, use limits, return rules, damage and loss, insurance, late fee and contacts.',
   'Check identity and, for vehicles, the right driver licence category and experience.',
   'Refuse or ask for training when the customer cannot use the item safely.',
   'Have a lawyer check the contract under the relevant federal rules. Keep a signed copy.'],
  'Customer wants a petrol cutter saw for a roof job on a ladder. Judge: high risk, no guard or training; ask for operator training, protective equipment and a safe set-up, or decline.',
  'Write a one-page contract for one item with the 13 terms. Judge three customer requests.',
  'All 13 terms present; three judgements justified with risk.'),
 ('Inspection, handover and returns', 'Apply', 5,
  'Evidence at the start and end of a rental settles disputes fast. Inspect every time.',
  ['Check-out: clean item, working, fuel or charge level, accessories, safety guards; photograph all sides with date and time.',
   'Show the customer how to use the item and give a one-page safety sheet. Record that you did so.',
   'Check-in: compare with the check-out photographs, test, and note hours or distance used.',
   'Settle on the day: refund deposit minus agreed charges, with a written reason for each charge.'],
  'Return of a van: 14:10 on the due date 12:00 = 2 hours 10 minutes late. Late fee rule: 150 RUB per started hour = 3 x 150 = 450 RUB. Fuel at 3/4 instead of full: 12 litres at 60 RUB = 720 RUB. Deposit 5,000 RUB - 1,170 RUB = 3,830 RUB refund.',
  'Complete a 12-point inspection form for check-out and check-in on a sample item and settle a return.',
  'Photograph list complete; charges tie to the contract; refund correct.'),
 ('Maintenance and downtime', 'Apply', 4,
  'A broken item earns nothing and can hurt a customer. Planned maintenance is cheaper than failure.',
  ['Make a schedule for each item: after every rental (clean, quick check), monthly, and by hours or kilometres as the maker advises.',
   'Keep a log: date, work done, parts, cost, who did it, and the next due date.',
   'Take any item with a safety fault out of service and tag it.',
   'Keep spare consumables such as blades, filters and oil to reduce downtime.'],
  'Generator serviced every 100 hours. Rented 8 hours a day for 5 days = 40 hours. After 3 rentals (120 hours) it is over by 20 hours; service due. Downtime 1 day costs 1 x 1,200 RUB rate.',
  'Create a service schedule and log for three items and mark which are overdue in a sample log.',
  'All service points set; overdue items found; fault tagging rule written.'),
 ('Insurance, damage and disputes', 'Evaluate', 4,
  'Know who pays when something goes wrong, and handle disputes with evidence and fairness.',
  ['Check insurance for the item, third-party injury, theft and your business. Read the exclusions.',
   'Separate fair wear from damage. Price repairs by quotes, not guesses, and send photos.',
   'Offer a calm, written process for disputes with a response time of 3 working days.',
   'Learn consumer rights that apply to services and keep within them.'],
  'Dent on a hired trailer: quote 6,500 RUB; deposit 8,000 RUB; contract has a 1,000 RUB excess. Charge 6,500 RUB, refund 1,500 RUB, attach quote and photos.',
  'Judge four damage cases as wear, damage, or fault of the owner, and compute charges.',
  'At least 3 of 4 correct; every charge matches a contract term.'),
 ('Design the rental business plan', 'Create', 4,
  'Bring it together in one pack and a monthly sheet that shows if the business is healthy.',
  ['Set monthly measures: utilisation, income per item, cost per rental day, damage cost, late rate and complaints.',
   'Review the worst three items and decide: reprice, promote or sell.',
   'Plan a growth step only when utilisation of existing stock is above your target.',
   'Write a risk list with actions: theft, accident, price war, seasonality.'],
  'Month: 10 items, 300 item-days available, 120 rented = 40 percent utilisation. Income 96,000 RUB, costs 70,000 RUB. Operating result 26,000 RUB. Target 50 percent.',
  'Assemble the pack and a mock month sheet for your fleet.',
  'All parts present; calculations correct; one improvement action per weak item.')],
 quiz=[('Define utilisation.', 'Days rented divided by days available, as a percent.'),
  ('A tool costs 9,000 RUB with a 3-year life. What is the daily ownership cost?', 'About 8.2 RUB per day (9,000 / 1,095).'),
  ('Why include a repair reserve?', 'Because unplanned repair is common; 10 to 15 percent protects margin.'),
  ('Name six required contract terms.', 'Parties, item and serial number, period, price, deposit, return rules, damage and loss, late fee.'),
  ('When should you decline a rental?', 'When the customer cannot use the item safely or lacks the needed licence or training.'),
  ('How does a deposit refund work?', 'Refund after inspection minus agreed charges, each with a written reason.'),
  ('What evidence do you collect at hand-over?', 'Dated photographs, a condition report and a note that safety instructions were given.'),
  ('What do you do with an item that has a safety fault?', 'Take it out of service, tag it and repair before renting again.'),
  ('A van is 2 h 10 min late with a rule of 150 RUB per started hour. What is the fee?', '3 started hours x 150 = 450 RUB.'),
  ('Why review the worst three items monthly?', 'To reprice, promote or sell items that drag down returns.')],
 rubric=[('Cost and pricing', 'Prices without costs.', 'Cost per day and margin shown.', 'Adds scenarios for low and high utilisation.'),
  ('Contract quality', 'Missing terms.', 'All terms present and clear.', 'Plain-language summary and lawyer-check note.'),
  ('Inspection discipline', 'No photos or signatures.', 'Complete before and after record.', 'Spots wear versus damage consistently.'),
  ('Safety and suitability', 'Rents without checks.', 'Checks licence, training and risk.', 'Offers safer alternatives to the customer.'),
  ('Maintenance and review', 'No schedule.', 'Schedule and log kept.', 'Uses the monthly sheet to change decisions.')],
 ladder=['L1 Basic: explain what rental is and why condition checks matter (awareness only).',
  'L2 Awareness: describe a price list, deposit and contract.',
  'L3 Foundation: run check-out and check-in under supervision.',
  'L4 Practitioner: price, contract, inspect and maintain a small fleet.',
  'L5 Specialist: manage one category such as vehicles or construction machines with specialist rules.',
  'L6 Advanced: lead several sites, fleet purchases and insurers.',
  'L7 Super expert: design fleet strategy and risk systems for large operators (note: always inside licensing and safety rules).'],
 jobs=[('Rental counter assistant', 'Handles bookings, hand-over and returns.'),
  ('Fleet technician', 'Services and tests rental items.'),
  ('Rental coordinator', 'Plans bookings, delivery and utilisation.'),
  ('Small rental business owner', 'Runs pricing, contracts and maintenance.'),
  ('Damage and claims clerk', 'Documents damage and settles deposits.')],
 next='Related generic courses: Small Business Records, Equipment Maintenance Basics, Customer Service and Contracts.')

C35 = dict(
 id='RU-35', title='Bitcoin Mining (Legal-Compliance-First Analysis)',
 summary='Learn to analyse a digital asset mining operation in the right order: first the legal and licensing check, then power, hardware, cooling, records, tax reporting and risk. No result is promised and nothing here helps avoid any rule.',
 level='L4 Practitioner',
 outcomes=[('Understand', 'Explain how proof-of-work mining works and what hash rate, difficulty, block reward and fees mean.'),
  ('Apply', 'Complete a rules check that records which activity is allowed, by whom, where and with what registration or reporting.'),
  ('Analyse', 'Calculate energy use, cost per day and cost per unit of hash rate for a given machine and tariff.'),
  ('Evaluate', 'Judge whether a project passes a go or no-go decision on legal status, power, heat, noise, records and risk.'),
  ('Create', 'Design a compliance and operations file for a small, lawful site with records, monitoring and an exit plan.')],
 task='Produce a go or no-go file for one proposed small mining site (written case), with a rules check, power and heat calculation, cost model, records plan and risk register.',
 condition='Open-book; 6 hours; calculator and templates; no machines bought or run; no wallet keys or real funds used.',
 standard='Rules check completed before any cost model; energy and heat calculations error-free; assumptions labelled as illustrative; five risks with actions; decision justified in one page; pass mark 80 percent.',
 who='People who want to understand mining as an energy-using, regulated activity, and advisers or owners who must judge whether a project is lawful and sensible.',
 req='Adult learner; basic arithmetic and spreadsheet skills. No prior crypto knowledge needed.',
 safety='The legal status of mining and of digital assets varies by country and changes often. In the Russian Federation, mining may be restricted, registered, reported or taxed under federal rules, and some regions or periods may limit it; electricity connection, building, fire and noise rules also apply. Before any step, check with the competent Russian authority and a qualified local lawyer and tax adviser. This course teaches analysis only. It never helps to evade a rule, hide activity, avoid reporting or use stolen power. Prices are volatile and returns are not promised; do not borrow to mine.',
 evidence='Evidence: rules check sheet, power and heat calculation, cost model with stated assumptions, records plan, risk register and a one-page go or no-go decision.',
 modules=[
 ('How mining works', 'Understand', 4,
  'Mining is a computing process that secures a network and, when it succeeds, earns a reward. Understanding the mechanism makes the cost and risk clear.',
  ['Miners compete to find a valid block using computation; the network sets a difficulty so blocks arrive about every 10 minutes.',
   'Hash rate is computations per second. A machine of 100 TH/s does 100 trillion per second.',
   'A miner\'s expected share of rewards roughly equals its share of the total network hash rate. Luck causes short-term variation, which pools smooth.',
   'Rewards come from the block subsidy and fees; the subsidy halves about every four years, so economics change on a schedule.'],
  'Illustrative only: if the network had 600 EH/s (600,000,000 TH/s) and a machine had 100 TH/s, its share is 100 / 600,000,000 = 0.000000167 (about 1 in 6 million). With 144 blocks a day this share is tiny, so mining at small scale usually runs through a pool.',
  'Write a half-page explanation for a lay reader of hash rate, difficulty and a pool, with one diagram.',
  'All terms correct; diagram shows block, difficulty and reward flow.'),
 ('The rules check comes first', 'Apply', 5,
  'Before any purchase, find out if the activity is lawful for this person, in this place, in this way. A project that fails this step stops here.',
  ['List the questions: Is mining allowed for this type of person or company? Is registration, reporting or licensing needed? Are there regional limits? How are income and assets taxed?',
   'Check the site: ownership or lease, permitted use of the building, electricity contract type, fire and noise rules, neighbours.',
   'Write each answer with its source (the competent authority or a qualified adviser), the date and the person who gave it. Rules change; recheck every 6 months.',
   'If any answer is unclear, the result is "not yet" and no money is spent.'],
  'Rules check sheet of 12 questions: 9 answered with source and date, 3 unclear. Result: stop at "not yet" until the 3 unclear items are answered in writing.',
  'Complete a rules check for a written case. Mark each answer: confirmed, unclear or not allowed.',
  'All 12 questions covered; sources and dates present; decision follows the rule that unclear means stop.'),
 ('Power: the main cost', 'Analyse', 5,
  'A miner turns almost all electricity into heat. Power cost and capacity usually decide whether a site makes sense.',
  ['Energy use (kWh) = power (kW) x hours. A 3,000 W machine uses 3 kW x 24 = 72 kWh a day.',
   'Efficiency = watts divided by TH/s, shown as J/TH. Lower is better.',
   'Use a legal electricity contract and a certified electrician. Check the circuit rating, cable size and protection; machines run at full load day and night.',
   'Never use unmetered, stolen or borrowed power.'],
  '3,000 W machine at 100 TH/s = 30 J/TH. Daily energy 72 kWh. At a tariff of 5 RUB per kWh: 360 RUB per day, 10,800 RUB for 30 days. At 6 RUB per kWh: 12,960 RUB. A 16 A circuit at 230 V supports about 3.7 kW, so one machine fits with little margin.',
  'Calculate daily and monthly energy cost and the circuit load for three machines and two tariffs.',
  'All calculations correct; circuit limit checked; efficiency compared in J/TH.'),
 ('Heat, noise and site safety', 'Apply', 4,
  'Every watt becomes heat, and fans are loud. Poor cooling and wiring are fire risks.',
  ['Heat output equals electrical input: 3,000 W gives about 3 kW of heat, similar to a room heater on full.',
   'Plan fresh air in and hot air out; keep temperatures within the maker\'s range and measure them.',
   'Keep distance from combustibles, use fire detection and an extinguisher, and follow building rules. Check noise limits for neighbours and workplaces.',
   'Place machines on stable, non-flammable shelves with space for airflow.'],
  '10 machines of 3 kW = 30 kW of heat. A room of 50 cubic metres would warm quickly, so ventilation of several thousand cubic metres an hour is needed. A professional should size it.',
  'Draw a site layout with airflow, power feed, fire equipment and a noise estimate for 4 machines.',
  'Heat total correct; airflow and exit paths shown; fire plan listed.'),
 ('Cost model with honest assumptions', 'Analyse', 5,
  'A cost model is a tool for questions, not a forecast. It must state assumptions and show what changes the answer.',
  ['List costs: hardware, power, cooling, space, network, staff time, repairs, fees and taxes.',
   'Compute cost per day and the price per coin at which the day\'s cost is covered (break-even price). This tells you how exposed you are.',
   'Test sensitivity: power cost up 20 percent, difficulty up 10 percent, coin price down 30 percent. Show each separately.',
   'Include an end-of-life value for hardware that is low, and never assume the future price.'],
  'Daily cost: power 360 RUB + cooling and space 60 RUB + repair reserve 30 RUB = 450 RUB. If the machine yields 0.00015 coin a day (illustrative), break-even price = 450 / 0.00015 = 3,000,000 RUB per coin; the project loses money at any price below that.',
  'Build a cost model for one machine with 5 sensitivity cases.',
  'Break-even price calculated; all assumptions labelled illustrative; sensitivities shown one at a time.'),
 ('Records, wallets and reporting', 'Apply', 4,
  'Good records show income, costs and compliance. Security protects funds from theft.',
  ['Record each reward received: date, amount, value in RUB at that date, wallet address and source.',
   'Keep costs: invoices for hardware, electricity bills, repairs, with dates.',
   'Reporting and tax: follow the rules the competent authority and your adviser confirm. Do not move assets to hide them.',
   'Wallet security: use hardware wallets or well-reviewed secure storage, keep backups of recovery phrases offline, never share them, and use two-factor access.'],
  'Month with 3 reward payments: 0.00002 coin each valued at 3,000,000 RUB per coin on the day = 60 RUB, 3 payments = 180 RUB. Ledger lines: date, amount, rate, RUB value, wallet.',
  'Fill a 10-line ledger and write a one-page security checklist.',
  'RUB values correct; recovery phrase rules stated; no mixing of personal and business wallets.'),
 ('Risk, fraud and scams', 'Evaluate', 4,
  'The field has many scams and hard risks. Knowing them protects money and reputation.',
  ['Beware promises of fixed returns, cloud mining sold with guarantees, requests for upfront fees and pressure to act fast.',
   'Buy hardware from the maker or a traceable seller. Check warranty, delivery times and import rules.',
   'Main risks: price fall, difficulty rise, hardware failure, rule change, power outage, theft, fire. Give each a likelihood, effect and action.',
   'Never borrow to buy machines; plan for a stop and sale of hardware.'],
  'Risk score = likelihood (1 to 3) x effect (1 to 3). Rule change 2 x 3 = 6; fire 1 x 3 = 3; price fall 3 x 2 = 6. Actions: recheck rules every 6 months; fit detection; keep a reserve of 3 months of costs: 450 RUB x 90 = 40,500 RUB per machine.',
  'Review three advertised offers for scam flags and write a risk register of 5 entries.',
  'All flags found; risk scores calculated; each risk has an action and owner.'),
 ('Decision file and exit plan', 'Create', 4,
  'The final product is a plain, honest decision with its evidence, including how to stop.',
  ['One page: decision (go, not yet, no-go), reasons, conditions to meet, review date.',
   'Attach the rules check, power and heat sheet, cost model, ledger plan and risk register.',
   'State triggers to stop: rule change, power tariff above a limit, unmet safety item, or running below break-even for 60 days.',
   'Write the exit plan: switch off, record, sell or recycle hardware lawfully.'],
  'Example: decision "not yet": three rule answers missing; circuit margin only 0.7 kW; conditions: written answers, a certified electrician\'s report, review date in 30 days. Stop trigger: tariff above 7 RUB per kWh.',
  'Write the go, not yet or no-go file for your case with attachments.',
  'Decision matches the rules check; triggers measurable; exit plan lawful.')],
 quiz=[('What comes first in this course, before costs?', 'The legal and licensing rules check.'),
  ('What does an unclear answer in the rules check mean?', 'Stop and spend nothing until it is answered in writing by the competent source.'),
  ('A machine uses 3 kW for 24 hours. What is the energy?', '72 kWh.'),
  ('At 5 RUB per kWh, what is that cost?', '360 RUB per day.'),
  ('What is J/TH?', 'Efficiency: energy per unit of hash; lower is better.'),
  ('Where does the electricity go?', 'Almost all becomes heat, so cooling and ventilation are needed.'),
  ('What is a break-even price?', 'The coin price at which a day\'s revenue covers that day\'s cost.'),
  ('Name two scam flags.', 'Guaranteed returns and demands for upfront fees or fast action.'),
  ('Why must power be metered and lawful?', 'Unmetered or stolen power is unlawful and unsafe.'),
  ('Name two stop triggers.', 'A rule change and a power tariff above the agreed limit.')],
 rubric=[('Rules check', 'Costs done first or sources missing.', 'All questions answered with sources and dates.', 'Adds a review calendar and who to ask.'),
  ('Energy and heat', 'Errors in kWh or kW.', 'All calculations correct.', 'Adds circuit and airflow checks.'),
  ('Cost model', 'Hidden or forecast-like assumptions.', 'Assumptions labelled; break-even shown.', 'Sensitivity cases one at a time.'),
  ('Records and security', 'No ledger.', 'Ledger and wallet rules complete.', 'Matches costs and rewards by month.'),
  ('Decision quality', 'Decision unsupported.', 'Decision follows the evidence.', 'Includes stop triggers and exit plan.')],
 ladder=['L1 Basic: say what mining is and that rules and power come first (awareness only).',
  'L2 Awareness: explain hash rate, difficulty and block reward.',
  'L3 Foundation: calculate energy use and cost for one machine.',
  'L4 Practitioner: complete a rules check and a go or no-go file for a small site.',
  'L5 Specialist: assess power, cooling and records for a multi-machine site with licensed engineers.',
  'L6 Advanced: lead compliance reviews and risk models for several sites.',
  'L7 Super expert: advise on policy and energy system impact (note: always within the law and with regulator approval).'],
 jobs=[('Mining site analyst', 'Prepares rules check and cost models for proposals.'),
  ('Compliance assistant (digital assets)', 'Keeps records and tracks rule changes.'),
  ('Facilities and power technician', 'Maintains power, cooling and monitoring.'),
  ('Equipment operations technician', 'Monitors and services machines.'),
  ('Energy analyst', 'Studies load, tariffs and heat use.')],
 next='Related generic courses: Energy and Power Basics, Data Centre Operations, Financial Records and Tax Basics.')

C36 = dict(
 id='RU-36', title='Drones',
 summary='Learn to plan and fly small unmanned aircraft lawfully and safely for inspection, mapping and imaging: rules, risk assessment, flight planning, image-quality calculations, data handling and records.',
 level='L4 Practitioner',
 outcomes=[('Understand', 'Explain the parts of a small unmanned aircraft and how weight, wind and battery limit a flight.'),
  ('Apply', 'Complete a pre-flight check, a flight log and a post-flight check without missing a step.'),
  ('Analyse', 'Calculate ground sample distance, image footprint, line spacing and flight time for a mapping job.'),
  ('Evaluate', 'Judge a planned flight against airspace, people, weather and equipment limits and decide go or no-go.'),
  ('Create', 'Design a mission plan with a risk assessment, permissions list, emergency actions and data plan.')],
 task='Plan one inspection or mapping mission over a written site (about 20 hectares), with a legal and airspace check, risk assessment, flight plan calculations, checklist set and data plan.',
 condition='Open-book; 6 hours; map, calculator, templates; no live flying is required for the written assessment; any practice flight is on a permitted site with a supervisor.',
 standard='Permissions list complete; GSD, spacing and flight time calculated within 5 percent of the key; risk assessment covers 8 hazards; go or no-go decision justified; pass mark 80 percent.',
 who='People who want to use small drones for survey, inspection, farming, media or public safety work, and managers who commission such work.',
 req='Adult learner; basic arithmetic and map reading. Pilots may need registration, training or certification as the rules require.',
 safety='Unmanned aircraft flights are regulated. Registration, pilot qualification, permission to use airspace, restricted and prohibited zones, flights over people, privacy and data protection, and rules for carrying loads all apply, and they change. Check with the competent Russian authority and a local adviser before every type of flight. Never fly near airports, crowds, critical sites or beyond the rules. This course does not authorise any flight.',
 evidence='Evidence: permissions list, risk assessment, mission plan with calculations, three checklists, flight log sample and a data plan.',
 modules=[
 ('Rules, airspace and permissions', 'Understand', 5,
  'The first question for any flight is whether it is allowed. Rules depend on aircraft mass, location, purpose and the pilot.',
  ['Sort aircraft by mass category as set in the relevant federal rules, because registration and permission needs depend on it.',
   'Check airspace: controlled zones, restricted and prohibited areas, nearby airports, power lines and critical sites.',
   'Obtain permission to use the airspace where it is required, and the landowner\'s consent to take off and land.',
   'Respect privacy: do not film people or private property without lawful grounds; follow data rules.'],
  'Permissions list for one job: aircraft mass 0.9 kg (category per rules), registration done, airspace request submitted 3 days before, landowner letter signed, insurance valid to 31 December, area 2.4 km from the nearest airfield boundary.',
  'Build a permissions list for a written site with 10 items and mark each as done, to do or not allowed.',
  'All 10 items checked; any not-allowed item stops the plan.'),
 ('Aircraft, power and the physics of flight', 'Understand', 4,
  'A multirotor lifts by thrust against weight; a fixed wing flies on lift. Know the main parts and limits.',
  ['Parts: frame, motors, propellers, flight controller, sensors, radio link, battery, camera or payload.',
   'Thrust-to-weight ratio of at least 2 gives control margin. A 1.2 kg aircraft needs at least 2.4 kg of total thrust.',
   'Battery energy (Wh) = voltage x capacity in Ah. Flight uses 70 to 80 percent of capacity; keep a reserve.',
   'Cold, altitude and wind all reduce flight time; payload mass reduces it more.'],
  'Battery 15.2 V x 5.0 Ah = 76 Wh. Average draw 220 W gives 76 / 220 = 0.345 h = 20.7 min total; usable 75 percent = 15.5 min. A 10 percent loss in cold cuts this to 14 min.',
  'Calculate the flight time of three aircraft and set a land-by time for each.',
  'Energy and times correct; reserve applied.'),
 ('Weather and site conditions', 'Evaluate', 4,
  'Wind, rain and visibility decide go or no-go as much as the aircraft does.',
  ['Use the maker\'s limits: for small aircraft often about 10 m/s of wind at height. Take gusts into account and stay well below the limit.',
   'No flight in rain, fog or poor light unless the aircraft and rules allow it. Keep visual line of sight where required.',
   'Walk the site: obstacles, trees, wires, people, roads, take-off and landing area, emergency landing spots.',
   'Record weather at the start of the mission: wind, temperature, cloud and visibility.'],
  'Forecast wind 7 m/s gusts 11 m/s; aircraft limit 10 m/s. Decision: no-go until gusts fall below 8 m/s. Re-check in 60 minutes.',
  'Make go or no-go calls for five weather cases and justify each in one line.',
  'At least 4 of 5 correct; gusts and limits compared.'),
 ('Risk assessment and emergencies', 'Analyse', 5,
  'A written assessment finds what can go wrong and what you will do. It shapes the flight plan.',
  ['List hazards: loss of link, low battery, GPS error, bird strike, collision, flyaway, fire from battery, person approaching.',
   'Score likelihood (1 to 3) x effect (1 to 3) and add a control for scores of 4 or more.',
   'Set return-to-home height above the tallest obstacle plus 20 metres, and test failsafe settings.',
   'Handle battery damage safely: swollen cells are removed, not charged, and stored in a non-flammable container.'],
  'Hazard: loss of link over a road. 2 x 3 = 6. Controls: fly away from the road, return-to-home at 60 m (tallest tree 35 m + 20 m = 55 m, rounded up), safety observer on the road side.',
  'Complete a risk table of 8 hazards for the case site.',
  'Eight hazards scored; every 4+ has a control; return height calculated.'),
 ('Mission planning for mapping', 'Apply', 5,
  'Mapping needs overlapping images at a known height. The numbers decide the quality and the battery plan.',
  ['GSD (cm per pixel) = sensor width (mm) x height (m) x 100 divided by focal length (mm) x image width (px).',
   'Image footprint width = GSD x image width in pixels. Line spacing = footprint x (1 - side overlap).',
   'Use about 75 percent front and 65 to 70 percent side overlap for survey.',
   'Flight time = total line length divided by speed, plus turns and take-off and landing; split into batteries.'],
  'Sensor 13.2 mm, focal 8.8 mm, 5472 px, height 100 m: GSD = 13.2 x 100 x 100 / (8.8 x 5472) = 2.74 cm/px. Footprint 150 m. At 70 percent side overlap the spacing is 45 m. Site 200,000 square metres: line length about 4,444 m; at 8 m/s = 556 s = 9.3 min, one battery.',
  'Compute GSD, footprint, spacing and flight time for a 40 ha site at 80 m, and the number of batteries.',
  'Each value within 5 percent; battery count follows the land-by time.'),
 ('Inspection and imaging work', 'Apply', 4,
  'For roofs, towers, pipelines and crops, the plan changes: smaller distances, angles and safe stand-off.',
  ['Keep a safe stand-off from structures, lines and people; do not fly near energised lines without the owner\'s approval and a competent person.',
   'Choose the camera angle and distance so a defect of 5 mm appears at least 3 pixels wide; this sets the maximum distance.',
   'Capture overlapping photos with consistent light, and log location, time and image number for each.',
   'Mark and report defects by severity with photos, location and suggested follow-up by an expert.'],
  'Camera gives 0.2 mm per pixel at 2 m. To see a 5 mm crack at 3 pixels needs 1.67 mm per pixel; allowed distance up to about 2 x 8.3 = 16 m, but wind and safety limit it to 5 m.',
  'Plan an inspection route for a chimney or roof with distances, angles and a defect log template.',
  'Stand-off shown; resolution maths correct; log template complete.'),
 ('Data, records and privacy', 'Evaluate', 4,
  'Images and logs are valuable and sensitive. Keep them in order and protect people.',
  ['Name files with date, site and flight number. Back up to two places the same day.',
   'Keep flight logs: pilot, aircraft, battery, times, weather, issues and permissions used.',
   'Blur or remove people and vehicles when the purpose does not need them; follow the data rules and the client\'s terms.',
   'Quality-check maps with at least 5 ground control points; error should be within 2 times the GSD.'],
  '1,200 images of 20 MB = 24 GB per flight; two backups = 72 GB. A map with GSD 2.74 cm has an error limit of about 5.5 cm.',
  'Create a file naming plan, a log template and a backup and privacy note for a job.',
  'Naming works for 3 flights; backup rule and privacy step stated.'),
 ('Design the mission file', 'Create', 4,
  'Bring everything into one pack that a supervisor or client can review before you fly.',
  ['Cover sheet: purpose, area map, date, pilot, aircraft, observer, contacts.',
   'Attach permissions, risk table, calculations, checklists, weather rule and emergency plan.',
   'State a stop rule: any new person, wind above limit, link loss or low battery means land.',
   'Add a short debrief form to record lessons after each flight.'],
  'Pack for a 20 ha mapping job: 3 flights of 9 minutes, 2 batteries, 1 observer; decision: go if wind < 8 m/s and visibility > 5 km; stop rule written; debrief after landing.',
  'Assemble the mission file for the case site.',
  'All parts present; decision rule is measurable; calculations match the plan.')],
 quiz=[('What is the first question before any flight?', 'Whether the flight is allowed, covering registration, airspace, permission and the pilot\'s status.'),
  ('A battery is 15.2 V and 5.0 Ah. What is its energy?', '76 Wh.'),
  ('Why use only 70 to 80 percent of battery capacity?', 'To keep a reserve for return, cold, wind and ageing.'),
  ('What does a thrust-to-weight ratio of 2 give?', 'Control margin to climb and manoeuvre safely.'),
  ('Define GSD.', 'The ground distance represented by one image pixel, in cm per pixel.'),
  ('If footprint is 150 m and side overlap is 70 percent, what is line spacing?', '45 m.'),
  ('What do you do with a swollen battery?', 'Stop use, do not charge, and store in a non-flammable container.'),
  ('How is return-to-home height chosen?', 'Tallest obstacle plus a safety margin, such as 20 m.'),
  ('Why blur people in images?', 'To protect privacy when the job does not need identifiable people.'),
  ('When is a no-go correct?', 'When wind, gusts, visibility, airspace, people or equipment limits are not met.')],
 rubric=[('Legal and airspace', 'Plans without permissions.', 'Permissions list complete.', 'Adds dates, contacts and a backup site.'),
  ('Risk assessment', 'Few hazards.', 'Eight hazards, controls for 4+.', 'Controls tested in the plan.'),
  ('Calculations', 'Wrong GSD or time.', 'Within 5 percent.', 'Also gives a sensitivity to wind.'),
  ('Go or no-go judgement', 'Ignores limits.', 'Correct for 4 of 5 cases.', 'States re-check times and stop rule.'),
  ('Records and data', 'No logs.', 'Logs, naming and backup.', 'Privacy and accuracy checks added.')],
 ladder=['L1 Basic: name drone parts and say that rules apply to every flight (awareness only).',
  'L2 Awareness: explain airspace zones, weather limits and battery care.',
  'L3 Foundation: fly a small aircraft on a permitted site under supervision and complete checklists.',
  'L4 Practitioner: plan, risk-assess and log an inspection or mapping mission.',
  'L5 Specialist: specialise in photogrammetry, thermal inspection or agriculture work.',
  'L6 Advanced: lead a team, quality system and permissions process for a drone service.',
  'L7 Super expert: advise on safety cases and standards for complex operations (note: only as the regulator permits).'],
 jobs=[('Drone pilot', 'Flies planned missions under the rules.'),
  ('Aerial survey technician', 'Plans mapping flights and processes data.'),
  ('Inspection operator', 'Collects images of structures and lines.'),
  ('Drone maintenance technician', 'Services aircraft, batteries and radios.'),
  ('Operations and permissions coordinator', 'Prepares permissions, risk files and logs.')],
 next='Related generic courses: Aerial Photography, Surveying and Mapping, Electronics and Battery Safety.')

C37 = dict(
 id='RU-37', title='Oil and Gas',
 summary='Learn the oil and gas value chain from reservoir to pipeline: geology basics, drilling, production measurement, process safety, pipelines and storage, environment and the licensing and compliance duties that surround every task.',
 level='L4 Practitioner',
 outcomes=[('Understand', 'Explain the stages of the oil and gas value chain and the role of each discipline.'),
  ('Apply', 'Convert and calculate volumes, rates, water cut and mass using correct units and a well-test record.'),
  ('Analyse', 'Interpret a production record and find the likely cause of a decline or a measurement error.'),
  ('Evaluate', 'Judge a work plan against permit-to-work, gas detection, hot-work and isolation rules and decide if it may start.'),
  ('Create', 'Design a field operating routine with safety checks, measurements, records and reporting.')],
 task='Prepare an operating pack for one written oil and gas production site: a flow and unit calculation, a safety and permit analysis, a monitoring routine and an incident and spill response sheet.',
 condition='Open-book; 7 hours; calculator, conversion table and templates; written case only; no field work or live equipment.',
 standard='Unit conversions error-free; mass balance within 2 percent; permit analysis finds all 6 planted gaps; response sheet lists first actions within 10 minutes; pass mark 80 percent.',
 who='People who plan to work or train in oil and gas operations, service companies, supply chains, safety or environment roles.',
 req='Adult learner; basic mathematics and science. Site entry requires medical fitness, site induction and employer-approved competence.',
 safety='Oil and gas work is highly regulated and dangerous: fire and explosion, toxic gas such as hydrogen sulphide, high pressure, confined spaces, heights, and environmental harm. Exploration, production, pipelines, storage and transport need licences, permits, trained and certified staff, industrial safety declarations and state supervision. Check with the competent Russian authority and a qualified adviser. This course is education only and does not authorise anyone to work on equipment; always follow the site\'s own procedures and stop work if unsure.',
 evidence='Evidence: unit and flow calculation sheet, mass balance, permit-to-work analysis, monitoring routine, spill response sheet and a compliance register.',
 modules=[
 ('The value chain and the rules around it', 'Understand', 4,
  'Oil and gas move through upstream (finding and producing), midstream (treating, storing, transporting) and downstream (refining and selling). Every stage has permits and supervision.',
  ['Upstream: surveys, exploration drilling, appraisal, development, production. Midstream: separation, treatment, pipelines, storage, loading. Downstream: refining and distribution.',
   'Subsurface rights, land use, environmental approvals, industrial safety and technical supervision are separate permissions; none replaces another.',
   'Local communities, workers and the environment can be harmed, so impact assessment, monitoring and reporting are required duties.',
   'Keep a compliance register: permit, holder, scope, expiry date and the person who checks it.'],
  'Register row: pipeline operation permit; holder: operator; scope: 12 km, 0.3 m diameter; expiry: 30 June; check: quarterly by the compliance lead; status: valid, renewal started 90 days ahead.',
  'Draw the value chain and fill a compliance register of 8 permissions for a written site.',
  'All stages shown; 8 permissions with owner and expiry; no gap in the checks.'),
 ('Geology and reservoir basics', 'Understand', 4,
  'Hydrocarbons are held in porous rock under a seal. Porosity and permeability decide how much is stored and how easily it flows.',
  ['A reservoir needs source rock, a porous reservoir rock, a seal and a trap. Missing any one means no accumulation.',
   'Porosity is the pore volume as a percent of rock volume; permeability is the ease of flow.',
   'Oil in place (stock-tank) = area x thickness x porosity x (1 - water saturation) divided by formation volume factor.',
   'Recovery factors vary widely; use only measured or approved values, never hopeful ones.'],
  'Area 2,000,000 m2, thickness 10 m, porosity 0.18, water saturation 0.30, volume factor 1.2: 2,000,000 x 10 x 0.18 x 0.70 / 1.2 = 2,100,000 m3 in place.',
  'Calculate in-place volume for two cases and explain which input matters most.',
  'Both results correct; inputs listed with units.'),
 ('Wells and drilling', 'Understand', 5,
  'Wells connect the reservoir to the surface. Drilling is risky; barriers keep pressure under control.',
  ['A well has casing strings, cement, a wellhead and a completion; each is a barrier or part of the barrier system.',
   'Drilling mud density balances formation pressure; too low risks an influx (kick), too high risks losses.',
   'Well control is a trained, certified function. Warning signs (pit gain, flow with pumps off) must lead to immediate shut-in under the site procedure.',
   'Record depth, mud weight, pressures and events on the daily drilling report.'],
  'Hydrostatic pressure = density x gravity x depth. Mud 1,200 kg/m3 at 2,500 m: 1,200 x 9.81 x 2,500 = 29.4 MPa. If formation pressure is 30 MPa, the well is under-balanced; raise the mud density under the site procedure.',
  'Calculate hydrostatic pressure at three depths for two mud densities and compare with a formation pressure.',
  'Calculations in MPa correct; balance state named; warning signs listed.'),
 ('Production measurement and units', 'Apply', 5,
  'You cannot manage what you do not measure. Correct units and test routines make reports reliable.',
  ['Well test gives total liquid rate, water cut and gas rate. Oil rate = liquid rate x (1 - water cut).',
   'Mass = volume x density. Typical crude is about 0.85 t per m3; 1 m3 = 6.29 barrels.',
   'Gas-oil ratio = gas volume divided by oil volume at standard conditions.',
   'Check calibration dates on meters and the allocation method between wells and the sales meter.'],
  'Test: liquid 120 m3/day, water cut 30 percent, gas 9,000 m3/day. Oil = 84 m3/day = 71.4 t/day = 528 barrels/day. GOR = 9,000 / 84 = 107 m3 of gas per m3 of oil.',
  'Process a 5-well test table: oil rate, mass, water cut change and GOR for each.',
  'All figures correct; units written on every line.'),
 ('Process safety, gas and hot work', 'Evaluate', 6,
  'Most major incidents come from loss of containment and ignition. The safeguards are simple and strict.',
  ['Permit-to-work: a written permit defines the task, hazards, isolation, gas test, people and time. Work does not start without it.',
   'Gas detection: flammable gas and toxic gas (hydrogen sulphide) must be monitored with calibrated detectors and personal alarms; leave at the first alarm and follow muster.',
   'Isolation: lock, tag and test before breaking a line. Verify zero pressure.',
   'Hazardous area equipment, grounding, and no ignition sources in classified areas. Hot work needs a gas test and a fire watch.'],
  'Hot work on a skid: gas test 0 percent of the lower explosive limit before work, repeated every 60 minutes; fire watch for 30 minutes after; isolation by double block and bleed, locked and tagged; permit valid 8 hours.',
  'Review three permits and find the 6 planted gaps.',
  'All gaps found; each fix is stated in one line.'),
 ('Pipelines, tanks and flow', 'Apply', 4,
  'Moving fluid safely means knowing flow, pressure, corrosion and leaks.',
  ['Flow rate Q = area x velocity. A pipe of 0.3 m inner diameter has an area of 0.0707 m2.',
   'Corrosion, erosion and third-party damage are the main failure causes; inspection and cathodic protection manage them.',
   'Tank measurements: level, temperature and water cut convert to net volume; check high-level alarms.',
   'Use leak detection by pressure and mass balance; investigate any imbalance over the set limit.'],
  'v = 1.5 m/s: Q = 0.0707 x 1.5 = 0.106 m3/s = 382 m3/h. Inlet 382 m3/h, outlet 372 m3/h: imbalance 10 m3/h = 2.6 percent, above a 2 percent alarm; start the leak investigation.',
  'Calculate flow and imbalance for 3 pipeline cases and decide whether to investigate.',
  'Flows and percent correct; decision matches the limit.'),
 ('Environment, spills and flaring', 'Evaluate', 4,
  'Operators must limit harm to air, water and soil, and report incidents to the competent authority.',
  ['Prevent: secondary containment, drip trays, inspection rounds, tank overfill protection.',
   'Respond: stop the source if safe, raise the alarm, contain, report, recover and clean under a plan with trained staff.',
   'Flaring and venting are monitored and limited under the relevant rules; measure and record volumes.',
   'Keep waste records and send waste only to licensed handlers.'],
  'Spill of 2 m3 on a bunded pad of 40 m2: depth if uncontained 5 cm; bund holds 15 m3, so the spill is contained. Actions: stop the leak, absorb, recover 2 m3, record, report as required, test soil.',
  'Complete a spill response sheet with first actions in 10 minutes and the reporting steps.',
  'Actions in order; contact roles named; waste route lawful.'),
 ('Design an operating routine', 'Create', 4,
  'Combine measurement, safety and compliance into a daily routine that others can follow.',
  ['Daily round: gauges, leaks, alarms, tank levels, safety equipment and records.',
   'Weekly: calibration checks, permit audit, drills. Monthly: production reconciliation and compliance register review.',
   'Define stop-work authority: anyone can stop work for safety.',
   'Set reporting lines and times for incidents, near misses and deviations.'],
  'Reconciliation: wells total 520 t/day; sales meter 508 t/day; tank change +6 t/day; losses 6 t/day (1.2 percent), within the 2 percent limit.',
  'Write a one-page routine and a reconciliation for a written 4-well site.',
  'Reconciliation within 2 percent; routine covers daily, weekly and monthly checks.')],
 quiz=[('Name the three stages of the value chain.', 'Upstream, midstream and downstream.'),
  ('What four elements must a reservoir have?', 'Source, reservoir rock, seal and trap.'),
  ('How is oil rate found from a well test?', 'Liquid rate x (1 - water cut).'),
  ('Convert 84 m3 of oil to tonnes at 0.85 t/m3.', '71.4 tonnes.'),
  ('What does a permit-to-work contain?', 'Task, hazards, isolation, gas test, people and valid time.'),
  ('What do you do at a gas alarm?', 'Stop, leave by the safe route and go to the muster point per the procedure.'),
  ('Why is hydrogen sulphide special?', 'It is toxic at very low levels and can disable the sense of smell; detection and escape rules are essential.'),
  ('A pipeline imbalance is 2.6 percent and the limit is 2 percent. What next?', 'Start the leak investigation and follow the procedure.'),
  ('Who may stop work for safety?', 'Anyone on site.'),
  ('Who checks permits and permissions?', 'The compliance lead against the register, and the competent authority through supervision.')],
 rubric=[('Units and calculations', 'Errors in units.', 'All conversions correct.', 'Adds checks and a sensitivity.'),
  ('Safety analysis', 'Misses permit gaps.', 'Finds all 6 gaps.', 'Gives root causes and fixes.'),
  ('Compliance', 'No register.', 'Register with owners and dates.', 'Includes renewal timing.'),
  ('Environment response', 'Unclear actions.', 'Ordered actions and roles.', 'Includes prevention and learning.'),
  ('Routine design', 'No schedule.', 'Daily, weekly and monthly routine.', 'Reconciliation with action limits.')],
 ladder=['L1 Basic: name the main parts of the chain and say that safety and permits come first (awareness only).',
  'L2 Awareness: explain wells, separators, pipelines and hazards.',
  'L3 Foundation: read gauges and records under supervision at site level.',
  'L4 Practitioner: calculate rates, review permits and prepare an operating routine.',
  'L5 Specialist: work in one discipline such as production, drilling support, process safety or environment.',
  'L6 Advanced: lead a team or asset and run audits and investigations.',
  'L7 Super expert: advise on safety cases, field development and regulation (note: only within licences and the law).'],
 jobs=[('Production operator trainee', 'Takes readings and records under supervision.'),
  ('Field technician', 'Maintains instruments and equipment.'),
  ('HSE officer', 'Checks permits, drills and incident reports.'),
  ('Production data analyst', 'Reconciles volumes and prepares reports.'),
  ('Logistics and supply coordinator', 'Plans supplies and transport for sites.')],
 next='Related generic courses: Industrial Safety and Permit-to-Work, Pipelines and Pumps, Environmental Management.')

C38 = dict(
 id='RU-38', title='Cosmetology and Pharmaceutics',
 summary='Learn the safe basics of cosmetic products and pharmacy practice: skin and hair science, ingredients, simple formulation arithmetic, hygiene and batch records, labelling, storage, dosing arithmetic, and the duty to refer and to stay inside licence.',
 level='L4 Practitioner',
 outcomes=[('Understand', 'Explain the legal and practical difference between a cosmetic, a medicine and a medical device.'),
  ('Apply', 'Calculate a batch formula by percent and weight, and fill in a batch and hygiene record.'),
  ('Analyse', 'Read a product label and ingredient list and flag allergen, preservative and claim issues.'),
  ('Evaluate', 'Judge a client or customer request and decide whether to proceed, refer to a qualified professional or decline.'),
  ('Create', 'Design a hygiene, storage and complaint system for a small cosmetic service or retail point.')],
 task='Produce a batch formula and record for a simple 5 kg cosmetic cream (written), a label check, a storage plan, a dose-arithmetic worksheet and a referral and complaints sheet.',
 condition='Open-book; 6 hours; calculator, templates and sample labels; written case only; no products made for sale and no advice given to real patients.',
 standard='Formula sums to 100 percent and the weights add up within 1 percent; batch record complete; label check finds 6 planted issues; referral decision correct for 4 of 5 cases; pass mark 80 percent.',
 who='Beauty and personal care workers, small cosmetic makers, pharmacy assistants and learners who wish to understand safety, quality and limits.',
 req='Adult learner; basic chemistry and arithmetic; clean hands and good hygiene habits.',
 safety='Cosmetic products, medicines and medical procedures are regulated. Making or selling cosmetics needs compliance with technical rules, safety assessment, labelling and sometimes registration; pharmacy work needs a qualified pharmacist, licensed premises and prescription rules; invasive treatments (injections, deep peels, lasers) need medical qualifications and licences. Check with the competent Russian authority and a local adviser. Nothing here is medical advice, and no product is claimed to cure disease. Refer skin conditions, infections and reactions to a doctor.',
 evidence='Evidence: batch formula and record, label check sheet, storage and hygiene plan, dose arithmetic worksheet, referral and complaints sheet and a short compliance note.',
 modules=[
 ('Scope, law and boundaries', 'Understand', 4,
  'What a product claims to do decides how it is regulated. A cosmetic cleans, perfumes, protects or changes appearance; a medicine treats or prevents disease.',
  ['Cosmetic: applied to skin, hair, nails or lips for cleaning, care or appearance. Medicine: claims to treat or prevent disease. Medical device: acts by physical means for a medical purpose.',
   'Claims like "cures acne" or "removes scars" turn a cosmetic into an unlawful medicine claim. Keep claims modest and true.',
   'Roles: a beautician works within cosmetic care; a pharmacist dispenses; a doctor diagnoses and prescribes. Know where your role stops.',
   'Keep records of product safety files, supplier certificates and staff training.'],
  'Claim check on five labels: "moisturises dry skin" OK; "heals eczema" not OK; "reduces the look of fine lines" OK; "cures fungal infection" not OK; "cleanses oily skin" OK. Result: 2 labels fail and must be rewritten.',
  'Sort 12 claims and tasks into cosmetic, medicine, device or refer. Explain 4 choices.',
  'At least 11 of 12 correct; each not-OK claim has a lawful rewrite.'),
 ('Skin, hair and common conditions', 'Understand', 4,
  'Skin is a barrier and an organ. Knowing normal structure and warning signs helps you care safely and refer in time.',
  ['The skin has an epidermis, dermis and subcutaneous layer; the surface is slightly acidic, around pH 4.5 to 5.5.',
   'Skin types: normal, dry, oily, combination and sensitive. Type can change with season and age.',
   'Warning signs that need a doctor: a changing or bleeding mole, spreading redness, pus, fever, severe pain, sudden hair loss or a rash with swelling.',
   'Sun protection and gentle cleansing are the base of care; avoid claims beyond that.'],
  'Client with a mole that changed colour over 2 months and has an uneven edge. Decision: do not treat or advise products; recommend a doctor visit soon; record the date and the referral.',
  'Describe five skin types, one care step each, and five warning signs with the action to take.',
  'All five types and warning signs correct; action is referral where needed.'),
 ('Ingredients, labels and safety', 'Analyse', 5,
  'The label is a legal document and a safety tool. Learn to read it and judge it.',
  ['The ingredient list uses standard international names in descending order of amount.',
   'Common groups: water, emollients, emulsifiers, humectants, thickeners, preservatives, fragrance, colour. Each has a role and limits.',
   'Allergens and restricted substances must be declared or limited under the relevant rules; check each against the official lists.',
   'Check the label: product name and function, net content, ingredients, batch, best-before or period-after-opening, maker\'s name and address, warnings.'],
  'Label check: net content missing, batch missing, "cures acne" claim, fragrance allergen not listed, maker address absent, open-jar symbol missing. 6 issues found; fix before sale.',
  'Check three sample labels and list issues with a lawful fix for each.',
  'At least 6 planted issues found; fixes are specific.'),
 ('Formulation arithmetic', 'Apply', 5,
  'Cosmetic formulas are written in percent of the total. Weights follow the percent exactly.',
  ['Weight = percent x batch weight. Parts must total 100 percent.',
   'Water phase and oil phase are heated and mixed with an emulsifier to make an emulsion; follow safe temperature and hygiene steps.',
   'Preservative level is set by the supplier data and legal limit. Never skip preservation in a water-based product.',
   'Check pH with a calibrated meter or strips; record it, and adjust only by a written method.'],
  'Batch 5.000 kg: water 70 percent = 3.500 kg; oils 25 percent = 1.250 kg; emulsifier 4 percent = 0.200 kg; preservative 1 percent = 0.050 kg. Total 5.000 kg. Tolerance for weighing: 1 percent of 0.050 kg = 0.0005 kg, so weigh to 0.1 g.',
  'Scale a formula to 2 kg, 5 kg and 12 kg and check the totals.',
  'Totals are 100 percent; weights within 1 percent; unit labels correct.'),
 ('Hygiene, GMP and batch records', 'Apply', 5,
  'Good manufacturing practice means clean people, clean rooms, clean equipment and written records so any batch can be traced.',
  ['Wash hands, wear clean clothing and a hair cover; no food or drink in the work area. Clean and sanitise surfaces and tools before and after.',
   'Keep a batch record: product, formula version, batch number, date, raw material lots, weights, temperatures, pH, operator, checks and release.',
   'Label raw materials with the date received and opened; use oldest first; quarantine rejected material.',
   'Keep a retained sample of each batch and test for appearance, smell, pH and microbial quality as required.'],
  'Batch 24-017: planned 5.000 kg, produced 4.920 kg; yield 98.4 percent. Raw lots recorded; pH 5.2 within 5.0 to 5.6; release signed by a second person.',
  'Complete a batch record for the 5 kg cream, including a deviation note for one planted error.',
  'Record complete; yield calculated; deviation recorded with action.'),
 ('Storage, shelf life and traceability', 'Apply', 4,
  'Storage and dating keep products safe. Traceability lets you recall a bad batch quickly.',
  ['Store cool, dry and away from sun. Medicines have stated storage ranges, such as 2 to 8 degrees Celsius for cold-chain products; follow the label.',
   'Keep a temperature log with checks at least twice daily for cold storage and act on any excursion.',
   'Period after opening (months) and minimum shelf life must be on the label; use first-expiry, first-out.',
   'Keep records to trace each batch to supplier and customer so a recall can reach everyone in 24 hours.'],
  'Fridge for cold-chain items: reading 9.5 degrees Celsius at 14:00, limit 8. Action: move stock to a working fridge, quarantine, record the time and duration, ask the maker or pharmacist whether the stock can be used.',
  'Make a storage plan with ranges, a log sheet and a mock recall sheet.',
  'Ranges stated; excursion action written; recall sheet traces 3 batches.'),
 ('Pharmacy basics: dispensing arithmetic and limits', 'Evaluate', 5,
  'Pharmacy work is precise and regulated. The arithmetic can be learned here, but dosing decisions belong to the prescriber and pharmacist.',
  ['Only a qualified pharmacist, with the licensed premises and a valid prescription where required, dispenses prescription medicines.',
   'Dose by weight: dose = mg per kg x weight in kg; volume = dose divided by concentration. Always use the figures on the prescription or the official instructions.',
   'Check the five rights: right person, medicine, dose, time and route; check allergies and interactions.',
   'Refer any doubt, error or reaction to the pharmacist or doctor at once.'],
  'Teaching arithmetic only: prescribed 15 mg per kg per dose, child 12 kg: 180 mg. Syrup is 120 mg per 5 mL: volume = 180 / 120 x 5 = 7.5 mL. Check by the pharmacist before any real use.',
  'Calculate five teaching doses and mark where a pharmacist check is required.',
  'All calculations correct; each case has a named checker; no real advice given.'),
 ('Reactions, complaints and referral system', 'Create', 4,
  'Good systems protect people when something goes wrong. Keep a clear path from complaint to learning.',
  ['Do a patch test as the product maker advises (for example, small area, 24 to 48 hours) before using a new product on a client, and record the result.',
   'If a reaction occurs, stop the product, rinse, advise medical help for swelling, breathing difficulty or blistering, and call emergency services if breathing is affected.',
   'Log each complaint with date, product, batch, symptoms, action and result; report serious events to the competent authority.',
   'Review the log monthly to find patterns by batch or supplier.'],
  'Month log: 1,200 uses, 6 mild reactions = 0.5 percent; 4 of 6 from batch 24-021. Action: quarantine the batch, contact the supplier, inform clients, record.',
  'Design a one-page referral, reaction and complaints system and apply it to five cases.',
  'Escalation path clear; batch pattern found; records complete.')],
 quiz=[('What makes a product a medicine rather than a cosmetic?', 'A claim or purpose to treat or prevent disease.'),
  ('Name two warning signs that need a doctor.', 'A changing or bleeding mole, spreading redness, pus, fever or severe pain.'),
  ('How are ingredients listed?', 'Using standard names in descending order of amount.'),
  ('A 5 kg batch has 4 percent emulsifier. What weight?', '0.200 kg.'),
  ('Why is preservative needed in a water-based product?', 'To stop microbes growing, which could harm users.'),
  ('What must a batch record let you do?', 'Trace the product to raw material lots, people, steps and checks.'),
  ('Cold-chain stock reads above its limit. What do you do?', 'Move and quarantine it, record the excursion and ask the maker or pharmacist about use.'),
  ('Compute a dose: 15 mg per kg, 12 kg child.', '180 mg, subject to a pharmacist\'s check.'),
  ('Who may dispense prescription medicines?', 'A qualified pharmacist in licensed premises, within prescription rules.'),
  ('What do you do if a client has swelling and breathing difficulty?', 'Call emergency services at once and stop the product.')],
 rubric=[('Law and boundaries', 'Makes medical claims.', 'Claims and tasks inside role.', 'Rewrites claims and names referrals.'),
  ('Formula and arithmetic', 'Totals not 100 percent.', 'Percent and weights correct.', 'Scales and checks tolerances.'),
  ('Label and ingredient review', 'Few issues found.', 'All planted issues found.', 'Fixes are specific and lawful.'),
  ('Hygiene and records', 'Gaps in records.', 'Complete batch record.', 'Includes deviation handling and trace.'),
  ('Referral and safety judgement', 'Treats or advises beyond role.', 'Correct decisions for 4 of 5.', 'Escalation and learning in the system.')],
 ladder=['L1 Basic: tell cosmetic from medicine and know when to refer (awareness only).',
  'L2 Awareness: describe skin types, common ingredients and hygiene rules.',
  'L3 Foundation: assist in a cosmetic service or pharmacy store under supervision.',
  'L4 Practitioner: prepare a formula, batch record, label check and referral system for a small operation.',
  'L5 Specialist: specialise in cosmetic formulation, skincare service or pharmacy support under licensed leaders.',
  'L6 Advanced: lead quality, safety files and staff training.',
  'L7 Super expert: advise on regulation and product safety strategy (note: only with the right licences and qualifications).'],
 jobs=[('Beauty therapist assistant', 'Provides routine cosmetic care within boundaries.'),
  ('Cosmetic production assistant', 'Weighs, mixes and records batches under supervision.'),
  ('Pharmacy assistant', 'Supports a pharmacist with stock, labels and customer service.'),
  ('Quality and labelling clerk', 'Checks labels, records and certificates.'),
  ('Retail skincare adviser', 'Advises on cosmetic products and refers health concerns.')],
 next='Related generic courses: Hygiene and Infection Control, Chemistry for Everyday Products, Retail and Customer Service.')

COURSES = [C32, C33, C34, C35, C36, C37, C38]
